def run(incident,findings,log_summary):
    related=[f for f in findings if f["id"] in incident["finding_ids"]]
    return {"incident_id":incident["id"],"evidence_summary":f"{len(incident['event_ids'])} source events and {len(related)} deterministic finding(s) are linked to this candidate incident.","alternative_explanations":["Automated authentication, shared egress infrastructure, or authorized testing may resemble abuse; verify with identity and change records."],"open_questions":["Were the accounts, source addresses, and timestamps expected?","Are related MFA, endpoint, or network events available?"],"recommended_steps":["Validate the timeline against authoritative identity logs.","Contact the account owner and check relevant change tickets.","Preserve related evidence and follow your incident response process."],"ai_summary":None}
